public static boolean isAsciiControl(char ch) {
    // Check if the character is less than 32 or equals to 127
    if (ch < 32 || ch == 127) {
        return true;
    }

    // Check if the character is a control character
    if (ch < 32 || ch > 126) {
        return true;
    }

    // Check if the character is one of the control characters
    if (ch == '\t' || ch == '\n' || ch == '\r') {
        return true;
